function surfY(x, z) {
  return 0.22 * Math.sin(0.85 * x) + 0.12 * Math.cos(1.1 * z) + 0.06 * x * z;
}
function surfYx(x, z) {
  return 0.22 * 0.85 * Math.cos(0.85 * x) + 0.06 * z;
}
function surfYz(x, z) {
  return -0.12 * 1.1 * Math.sin(1.1 * z) + 0.06 * x;
}
function surfacePoint(x, z) {
