}
function normalAt(x, z) {
  return new THREE.Vector3(-surfYx(x, z), 1, -surfYz(x, z)).normalize();
}
function tangentMetric(x, z) {
  const yx = surfYx(x, z), yz = surfYz(x, z);
  return Math.sqrt(1 + yx * yx + yz * yz);
}
function estimatePatchArea(cx, cz) {
  const n = 36;
  const x0 = cx - fig.dx / 2, z0 = cz - fig.dz / 2;
  let sum = 0;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const x = x0 + fig.dx * (i + 0.5) / n;
      const z = z0 + fig.dz * (j + 0.5) / n;
      sum += tangentMetric(x, z);
    }
  }
  return sum * fig.dx * fig.dz / (n * n);
}
function sampledSurfaceGeometry(x0, x1, z0, z1, nx, nz) {
  const positions = [];
  const indices = [];
  for (let j = 0; j <= nz; j++) {
    const z = z0 + (z1 - z0) * j / nz;
    for (let i = 0; i <= nx; i++) {
      const x = x0 + (x1 - x0) * i / nx;
      positions.push(x, surfY(x, z), z);
