function makeArrowInGroup(parent, start, dir, length, color, opts = {}) {
  const radius = opts.radius ?? 0.035;
  const headLen = Math.min(opts.headLen ?? 0.22, Math.max(length * 0.35, 0.02));
  const shaftLen = Math.max(length - headLen, 0.001);
  const shaftStart = start.clone();
  const shaftEnd = start.clone().add(dir.clone().multiplyScalar(shaftLen));
  makeCylinderBetween(shaftStart, shaftEnd, radius, color, parent);
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(opts.headRadius ?? radius * 3.2, headLen, 24),
