  const shaftEnd = start.clone().add(dir.clone().multiplyScalar(length * 0.78));
  makeCylinderBetween(start, shaftEnd, 0.035, colors.purple, normalGroup);

  const tip = start.clone().add(dir.clone().multiplyScalar(length));
  const base = start.clone().add(dir.clone().multiplyScalar(length * 0.78));
  const aux = Math.abs(dir.dot(new THREE.Vector3(0, 1, 0))) > 0.92 ? new THREE.Vector3(1, 0, 0) : new THREE.Vector3(0, 1, 0);
  const side = new THREE.Vector3().crossVectors(dir, aux).normalize().multiplyScalar(0.18);
  const verts = [tip, base.clone().add(side), base.clone().sub(side), tip];
  const line = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(verts),
    new THREE.LineBasicMaterial({ color: colors.purple })
  );
