}
function makeLeader(group, start, control, end) {
  clearGroup(group);
  const curve = new THREE.QuadraticBezierCurve3(start, control, end);
  const pts = curve.getPoints(48);
  const line = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: colors.black })
  );
  group.add(line);
  const tangent = pts[pts.length - 1].clone().sub(pts[pts.length - 3]).normalize();
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(0.09, 0.22, 24),
    new THREE.MeshBasicMaterial({ color: colors.black })
  );
  cone.position.copy(end).sub(tangent.clone().multiplyScalar(0.11));
  orientY(cone, tangent);
