}
function makeSweptVolume(cx, cz, nrm, length) {
  clearGroup(sweptGroup);
  if (length <= 0.001) return;
  const nx = 12, nz = 8;
  const x0 = cx - fig.dx / 2, x1 = cx + fig.dx / 2;
  const z0 = cz - fig.dz / 2, z1 = cz + fig.dz / 2;
  const base = [];
  const top = [];
  for (let j = 0; j <= nz; j++) {
    const z = z0 + (z1 - z0) * j / nz;
    for (let i = 0; i <= nx; i++) {
      const x = x0 + (x1 - x0) * i / nx;
      const p = surfacePoint(x, z);
      base.push(p);
      top.push(p.clone().add(nrm.clone().multiplyScalar(length)));
    }
