  const positions = [];
  base.concat(top).forEach(p => positions.push(p.x, p.y, p.z));
  const row = nx + 1;
  const topOffset = base.length;
  const idx = [];
  for (let j = 0; j < nz; j++) {
    for (let i = 0; i < nx; i++) {
      const a = topOffset + j * row + i, b = a + 1, c = a + row, d1 = c + 1;
      idx.push(a, c, b, b, c, d1);
