  }
  for (let i = 0; i < nx; i++) {
    const a = i, b = i + 1, c = topOffset + i, d1 = topOffset + i + 1;
    idx.push(a, b, c, b, d1, c);
    const j = nz;
    const e = j * row + i, f = e + 1, g = topOffset + e, h = topOffset + f;
    idx.push(e, g, f, f, g, h);
  }
  for (let j = 0; j < nz; j++) {
    const a = j * row, b = (j + 1) * row, c = topOffset + a, d1 = topOffset + b;
    idx.push(a, c, b, b, c, d1);
    const e = j * row + nx, f = (j + 1) * row + nx, g = topOffset + e, h = topOffset + f;
    idx.push(e, f, g, f, h, g);
