  s.lineTo(x0 + 1.92, y1 + 0.62);
  s.lineTo(x0 + 1.10, y1 + 0.62);
  s.lineTo(x0 + 1.10, y1 + 1.14);
  s.lineTo(x0 + 0.28, y1 + 0.38);
  s.lineTo(x0 + 1.10, y1 - 0.35);
