let nLabel, areaTextLabel, surfaceTextLabel, areaReadoutLabel, volumeReadoutLabel, calloutTextLabel;
let lastArea = 0;

function updateLabelsAndLeaders(center, nrm, area, sweptLen) {
  if (!nLabel) return;
