// @FIGURE_CODE_BEGIN
// compact surface top σ_k → sampled curved BufferGeometry MeshBasicMaterial translucent mint, enlarged
// visible front/right/left side faces → sampled side BufferGeometry MeshBasicMaterial pale green
// surface outline and bottom edges → cyan Line curves following top and side boundaries
// dashed interior surface curve → LineDashedMaterial cyan, across middle of patch
// sample point → SphereGeometry teal, draggable on σ_k
// normal vector n → dominant purple CylinderGeometry shaft plus hollow triangular LineLoop arrowhead
// flow arrows → two black cylinder-and-cone arrows beside patch, parallel to n
// area leader → long black QuadraticBezierCurve3 Line plus cone arrowhead toward top face
// surface leader → long black QuadraticBezierCurve3 Line plus cone arrowhead toward right face
// lower callout → camera-facing pale-yellow ShapeGeometry in overlay scene with gray outline and large left-pointing arrow
// visible labels → addLabel HTML for n, Area ΔS_k, Surface σ_k, and large callout sentence

document.getElementById('btnReset').style.display = '';

const fig = {
  xMin: -2.05, xMax: 2.05,
  zMin: -0.98, zMax: 0.98,
  thickness: 0.62,
  sampleX: 0.0,
  sampleZ: 0.0,
  velocity: 1.0
};

const colors = {
  cyan: 0x18bfc3,
  cyanDark: 0x0aa5aa,
  mint: 0xccebd5,
  sideMint: 0xbfe5cf,
  tealPoint: 0x19bfc0,
  purple: 0xb963b7,
  black: 0x202027,
  yellow: 0xffe3aa,
  gray: 0xa9a9a9,
  text: '#252128'
};

scene.add(new THREE.AmbientLight(0xffffff, 0.92));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.72);
keyLight.position.set(2.5, 4.5, 3.5);
scene.add(keyLight);

const overlayScene = new THREE.Scene();
const _baseRender = renderer.render.bind(renderer);
renderer.render = function patchedRender(s, c) {
  _baseRender(s, c);
  renderer.clearDepth();
  _baseRender(overlayScene, c);
};

function surfY(x, z) {
  return 0.20 * Math.cos(0.72 * x) - 0.115 * z + 0.047 * x * z;
}
function surfYx(x, z) {
  return -0.20 * 0.72 * Math.sin(0.72 * x) + 0.047 * z;
}
function surfYz(x, z) {
  return -0.115 + 0.047 * x;
}
function surfacePoint(x, z) {
  return new THREE.Vector3(x, surfY(x, z), z);
}
function bottomPoint(x, z) {
  const p = surfacePoint(x, z);
  p.y -= fig.thickness;
  return p;
}
function normalAt(x, z) {
  return new THREE.Vector3(-surfYx(x, z), 1, -surfYz(x, z)).normalize();
}
function clampSample() {
  fig.sampleX = Math.max(fig.xMin + 0.20, Math.min(fig.xMax - 0.20, fig.sampleX));
  fig.sampleZ = Math.max(fig.zMin + 0.18, Math.min(fig.zMax - 0.18, fig.sampleZ));
}

function disposeObject(obj) {
  obj.traverse?.(o => {
    o.geometry?.dispose?.();
    if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.());
    else o.material?.dispose?.();
  });
}
function clearGroup(group) {
  while (group.children.length) {
    const obj = group.children.pop();
    disposeObject(obj);
  }
}

function makeTopGeometry(nx = 72, nz = 34) {
  const pos = [];
  const idx = [];
  for (let j = 0; j <= nz; j++) {
    const z = fig.zMin + (fig.zMax - fig.zMin) * j / nz;
    for (let i = 0; i <= nx; i++) {
      const x = fig.xMin + (fig.xMax - fig.xMin) * i / nx;
      const p = surfacePoint(x, z);
      pos.push(p.x, p.y, p.z);
    }
  }
  const row = nx + 1;
  for (let j = 0; j < nz; j++) {
    for (let i = 0; i < nx; i++) {
      const a = j * row + i, b = a + 1, c = a + row, e = c + 1;
      idx.push(a, c, b, b, c, e);
    }
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  geom.setIndex(idx);
  geom.computeVertexNormals();
  geom.computeBoundingBox();
  geom.computeBoundingSphere();
  return geom;
}

function makeSideGeometry(side, n = 64) {
  const pos = [];
  const idx = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    let x, z;
    if (side === 'front') {
      x = fig.xMin + (fig.xMax - fig.xMin) * t;
      z = fig.zMin;
    } else if (side === 'back') {
      x = fig.xMin + (fig.xMax - fig.xMin) * t;
      z = fig.zMax;
    } else if (side === 'right') {
      x = fig.xMax;
      z = fig.zMin + (fig.zMax - fig.zMin) * t;
    } else {
      x = fig.xMin;
      z = fig.zMin + (fig.zMax - fig.zMin) * t;
    }
    const top = surfacePoint(x, z);
    const bot = bottomPoint(x, z);
    pos.push(top.x, top.y, top.z, bot.x, bot.y, bot.z);
  }
  for (let i = 0; i < n; i++) {
    const a = 2 * i, b = a + 1, c = a + 2, e = a + 3;
    idx.push(a, b, c, c, b, e);
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  geom.setIndex(idx);
  geom.computeVertexNormals();
  geom.computeBoundingBox();
  geom.computeBoundingSphere();
  return geom;
}

function curveX(x0, x1, z, top = true, n = 88) {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const x = x0 + (x1 - x0) * i / n;
    pts.push(top ? surfacePoint(x, z) : bottomPoint(x, z));
  }
  return pts;
}
function curveZ(z0, z1, x, top = true, n = 66) {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const z = z0 + (z1 - z0) * i / n;
    pts.push(top ? surfacePoint(x, z) : bottomPoint(x, z));
  }
  return pts;
}
function makeLine(mat, pts = [], parent = scene) {
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), mat);
  parent.add(line);
  return line;
}

const topMesh = new THREE.Mesh(
  makeTopGeometry(),
  new THREE.MeshBasicMaterial({
    color: colors.mint,
    transparent: true,
    opacity: 0.80,
    side: THREE.DoubleSide,
    depthWrite: false
  })
);
topMesh.renderOrder = 2;
scene.add(topMesh);
registerInteractive(topMesh, {
  title: 'Surface element σₖ',
  tooltip: 'Curved surface patch σₖ',
  body: 'This compact curved patch is the local surface element σₖ used in the flux approximation.'
});

const sideMat = new THREE.MeshBasicMaterial({
  color: colors.sideMint,
  transparent: true,
  opacity: 0.67,
  side: THREE.DoubleSide,
  depthWrite: false
});
['front', 'right', 'left'].forEach(side => {
  const mesh = new THREE.Mesh(makeSideGeometry(side), sideMat.clone());
  mesh.renderOrder = 1;
  scene.add(mesh);
});

const edgeMat = new THREE.LineBasicMaterial({ color: colors.cyan, linewidth: 2 });
const darkEdgeMat = new THREE.LineBasicMaterial({ color: colors.cyanDark, linewidth: 2 });
const dashMat = new THREE.LineDashedMaterial({
  color: colors.cyan,
  dashSize: 0.18,
  gapSize: 0.12,
  transparent: true,
  opacity: 0.92
});

[
  curveX(fig.xMin, fig.xMax, fig.zMin, true),
  curveX(fig.xMin, fig.xMax, fig.zMax, true),
  curveZ(fig.zMin, fig.zMax, fig.xMin, true),
  curveZ(fig.zMin, fig.zMax, fig.xMax, true),
  curveX(fig.xMin, fig.xMax, fig.zMin, false),
  curveZ(fig.zMin, fig.zMax, fig.xMax, false),
  curveZ(fig.zMin, fig.zMax, fig.xMin, false)
].forEach((pts, i) => makeLine(i === 0 || i === 5 ? darkEdgeMat.clone() : edgeMat.clone(), pts));

const hiddenCurve = makeLine(dashMat, curveX(fig.xMin + 0.32, fig.xMax - 0.32, 0.14, true, 80));
hiddenCurve.computeLineDistances();

const sampleSphere = new THREE.Mesh(
  new THREE.SphereGeometry(0.105, 30, 18),
  new THREE.MeshBasicMaterial({ color: colors.tealPoint })
);
scene.add(sampleSphere);
registerInteractive(sampleSphere, {
  title: 'Representative point',
  tooltip: 'Drag the teal point',
  body: 'The normal n is drawn at this representative point of σₖ. Drag it to see the normal reorient on the curved surface.'
});

const normalGroup = new THREE.Group();
const flowGroup = new THREE.Group();
const areaLeaderGroup = new THREE.Group();
const surfaceLeaderGroup = new THREE.Group();
scene.add(normalGroup, flowGroup, areaLeaderGroup, surfaceLeaderGroup);

function orientY(mesh, dir) {
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
}
function cylinderBetween(start, end, radius, color, parent, segments = 18) {
  const dir = end.clone().sub(start);
  const len = Math.max(dir.length(), 0.001);
  const mesh = new THREE.Mesh(
    new THREE.CylinderGeometry(radius, radius, len, segments),
    new THREE.MeshBasicMaterial({ color })
  );
  mesh.position.copy(start).add(end).multiplyScalar(0.5);
  orientY(mesh, dir);
  parent.add(mesh);
  return mesh;
}
function makeSolidArrow(parent, start, dir, length, color, opts = {}) {
  const d0 = dir.clone().normalize();
  const radius = opts.radius ?? 0.035;
  const headLen = opts.headLen ?? 0.24;
  const shaftLen = Math.max(length - headLen, 0.02);
  cylinderBetween(start, start.clone().add(d0.clone().multiplyScalar(shaftLen)), radius, color, parent, 16);
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(opts.headRadius ?? radius * 3, headLen, 24),
    new THREE.MeshBasicMaterial({ color })
  );
  cone.position.copy(start).add(d0.clone().multiplyScalar(shaftLen + headLen / 2));
  orientY(cone, d0);
  parent.add(cone);
}
function makeNormalArrow(start, dir) {
  clearGroup(normalGroup);
  const d0 = dir.clone().normalize();
  const length = 1.72;
  const shaftEnd = start.clone().add(d0.clone().multiplyScalar(length * 0.80));
  cylinderBetween(start, shaftEnd, 0.048, colors.purple, normalGroup, 24);

  const tip = start.clone().add(d0.clone().multiplyScalar(length));
  const base = start.clone().add(d0.clone().multiplyScalar(length * 0.80));
  camera.updateMatrixWorld();
  const camRight = new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld, 0).normalize();
  let side = camRight.clone().sub(d0.clone().multiplyScalar(camRight.dot(d0)));
  if (side.lengthSq() < 1e-5) side.set(1, 0, 0);
  side.normalize().multiplyScalar(0.21);
  const pts = [tip, base.clone().add(side), base.clone().sub(side), tip];
  const head = new THREE.LineLoop(
    new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: colors.purple })
  );
  normalGroup.add(head);
}
function makeLeader(group, start, control, end, color = colors.black) {
  clearGroup(group);
  const curve = new THREE.QuadraticBezierCurve3(start, control, end);
  const pts = curve.getPoints(64);
  const line = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color })
  );
  group.add(line);
  const tangent = pts[pts.length - 1].clone().sub(pts[pts.length - 5]).normalize();
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(0.088, 0.22, 24),
    new THREE.MeshBasicMaterial({ color })
  );
  cone.position.copy(end).sub(tangent.clone().multiplyScalar(0.095));
  orientY(cone, tangent);
  group.add(cone);
}

let nLabel, areaLabel, surfaceLabel, calloutTextLabel;
let currentCenter = surfacePoint(0, 0);
let currentNormal = normalAt(0, 0);

function updateFlowArrows(nrm) {
  clearGroup(flowGroup);
  if (fig.velocity <= 0.001) return;
  const len = 0.62 + 0.28 * fig.velocity;
  const leftBase = bottomPoint(fig.xMin - 0.34, fig.zMin + 0.15).add(new THREE.Vector3(0, -0.06, 0));
  const rightBase = bottomPoint(fig.xMax - 0.28, fig.zMin + 0.16).add(new THREE.Vector3(0, -0.04, 0));
  makeSolidArrow(flowGroup, leftBase, nrm, len, colors.black, { radius: 0.028, headLen: 0.24, headRadius: 0.095 });
  makeSolidArrow(flowGroup, rightBase, nrm, len, colors.black, { radius: 0.028, headLen: 0.24, headRadius: 0.095 });
}

function updateLabelsAndLeaders() {
  if (!nLabel || !areaLabel || !surfaceLabel) return;
  const tip = currentCenter.clone().add(currentNormal.clone().multiplyScalar(1.72));
  nLabel.pos.copy(tip).add(new THREE.Vector3(0.12, 0.15, 0.02));

  const areaPos = new THREE.Vector3(1.75, surfY(1.42, -0.14) + 1.42, -0.18);
  areaLabel.pos.copy(areaPos);
  const areaEnd = surfacePoint(0.86, -0.04).add(new THREE.Vector3(0, 0.075, 0));
  makeLeader(
    areaLeaderGroup,
    areaPos.clone().add(new THREE.Vector3(-0.38, -0.03, 0.04)),
    new THREE.Vector3(0.92, surfY(0.8, -0.10) + 1.55, -0.26),
    areaEnd
  );

  const surfPos = new THREE.Vector3(2.40, surfY(1.72, 0.35) + 0.56, 0.50);
  surfaceLabel.pos.copy(surfPos);
  const surfEnd = surfacePoint(fig.xMax, 0.06).add(new THREE.Vector3(0.05, -0.13, 0));
  makeLeader(
    surfaceLeaderGroup,
    surfPos.clone().add(new THREE.Vector3(-0.26, -0.08, 0.00)),
    new THREE.Vector3(2.18, surfY(1.85, 0.22) - 0.22, 0.64),
    surfEnd
  );
}

function updateAll() {
  clampSample();
  currentCenter = surfacePoint(fig.sampleX, fig.sampleZ);
  currentNormal = normalAt(fig.sampleX, fig.sampleZ);
  sampleSphere.position.copy(currentCenter);
  makeNormalArrow(currentCenter, currentNormal);
  updateFlowArrows(currentNormal);
  updateLabelsAndLeaders();
  positionCallout?.();
}

updateAll();

const authoredView = {
  projection: 'orthographic',
  axisScreenAngles: { x: 24, z: 26 },
  rollDeg: 0,
  target: [0.12, -0.20, 0],
  heightFraction: 0.73,
  distanceScale: 1.3
};
setCameraView(authoredView);

function cameraBasis() {
  camera.updateMatrixWorld();
  return {
    right: new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld, 0).normalize(),
    up: new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld, 1).normalize(),
    forward: new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld, 2).normalize()
  };
}

function makeCalloutShape() {
  const x0 = -2.35, x1 = 2.35, y0 = -1.05, yTop = 0.08, r = 0.28;
  const s = new THREE.Shape();
  s.moveTo(x0, yTop);
  s.lineTo(0.18, yTop);
  s.lineTo(0.18, -0.28);
  s.lineTo(-0.58, 0.43);
  s.lineTo(0.18, 1.14);
  s.lineTo(0.18, 0.76);
  s.lineTo(1.56, 0.76);
  s.quadraticCurveTo(x1, 0.76, x1, 0.34);
  s.lineTo(x1, y0 + r);
  s.quadraticCurveTo(x1, y0, x1 - r, y0);
  s.lineTo(x0, y0);
  s.lineTo(x0, yTop);
  return s;
}
function shapeOutline(shape) {
  return shape.getPoints(160).map(p => new THREE.Vector3(p.x, p.y, 0.014));
}

const calloutGroup = new THREE.Group();
const callShape = makeCalloutShape();
const callMesh = new THREE.Mesh(
  new THREE.ShapeGeometry(callShape),
  new THREE.MeshBasicMaterial({
    color: colors.yellow,
    transparent: true,
    opacity: 0.88,
    side: THREE.DoubleSide,
    depthWrite: false,
    depthTest: false
  })
);
const callOutline = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints(shapeOutline(callShape)),
  new THREE.LineBasicMaterial({ color: colors.gray, depthTest: false })
);
callMesh.renderOrder = 20;
callOutline.renderOrder = 21;
calloutGroup.add(callMesh, callOutline);
overlayScene.add(calloutGroup);

function positionCallout() {
  if (!calloutGroup) return;
  const b = cameraBasis();
  const halfH = d / (camera.zoom || 1);
  const halfW = halfH * aspect;
  const s = Math.min(halfH * 0.50, halfW * 0.36);
  calloutGroup.quaternion.copy(camera.quaternion);
  calloutGroup.scale.setScalar(s);

  const arrowTipLocal = new THREE.Vector3(-0.58, 0.43, 0);
  const anchor = surfacePoint(fig.xMax, fig.zMin + 0.32).add(new THREE.Vector3(0.12, -0.16, 0.02));
