    .sub(b.right.clone().multiplyScalar(arrowTipLocal.x * s))
    .sub(b.up.clone().multiplyScalar(arrowTipLocal.y * s))
    .add(b.forward.clone().multiplyScalar(0.16));

  if (calloutTextLabel) {
    calloutTextLabel.pos.copy(calloutGroup.localToWorld(new THREE.Vector3(-0.73, -0.57, 0.08)));
  }
}

nLabel = addLabel('<b>n</b>', new THREE.Vector3(), {
  color: colors.text,
  fontSize: '36px',
  bold: true,
  offset: [8, -2]
});
areaLabel = addLabel('Area ΔS<sub>k</sub>', new THREE.Vector3(), {
  color: colors.text,
  fontSize: '36px',
  offset: [8, -8]
});
surfaceLabel = addLabel('Surface&nbsp; σ<sub>k</sub>', new THREE.Vector3(), {
  color: colors.text,
  fontSize: '36px',
  offset: [10, 2]
});
calloutTextLabel = addLabel(
  '<div style="text-align:left;line-height:1.22;min-width:470px;">The volume of fluid<br>crossing <i>σ</i><sub>k</sub> in the<br>direction of <b>n</b> per<br>unit of time.</div>',
  new THREE.Vector3(),
  { color: colors.text, fontSize: '35px', offset: [0, 0] }
);

updateAll();
