  positionCallout();
}, true);

function setVelocity(v) {
  fig.velocity = Math.max(0, Math.min(3, v));
  document.getElementById('velocityMagnitude').value = fig.velocity.toFixed(1);
  document.getElementById('velReadout').textContent = fig.velocity.toFixed(1);
  updateAll();
}
document.getElementById('velocityMagnitude').addEventListener('input', e => setVelocity(parseFloat(e.target.value)));

const dragRaycaster = new THREE.Raycaster();
const dragPointer = new THREE.Vector2();
const dragPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
let draggingPoint = false;
let dragOffset = new THREE.Vector2();

function setDragPointer(e) {
  const rect = canvas.getBoundingClientRect();
